112	    for (const RegionArtifact& artifact : record.artifacts) {
113	        std::string words = artifact.type == "paint" ? artifact.target + " " + artifact.state + " paint" : region_artifact_words(artifact);
114	        if (std::find(made.begin(), made.end(), words) == made.end())
115	            made.push_back(words);
