127	// What a kind generates for a geometry, before facets are resolved.
128	inline std::vector<RegionArtifact> region_artifact_plan(const RegionRecord& record)
129	{
130	    const std::string& kind = record.kind;
131	    const std::string& type = record.geometry.type;
132	    const bool painted = type == "face" || type == "direction";
133	    std::vector<RegionArtifact> plan;
134	    const auto paint = [&](const char* target, std::string state) {
135	        plan.push_back({"paint", target, std::move(state), {}, record.part, {}});
136	    };
137	    const auto volume = [&](const char* target) { plan.push_back({"volume", target, {}, region_volume_name(record, target), 0, {}}); };
138	    if (kind == "smooth_face") {
139	        paint("support", "blocker");
140	        paint("seam", "blocker");
141	    } else if (kind == "no_support" || kind == "precision_hole") {
142	        painted ? paint("support", "blocker") : volume("support_blocker");
143	    } else if (kind == "support_allowed") {
144	        painted ? paint("support", "enforcer") : volume("support_enforcer");
145	    } else if (kind == "visible" || kind == "seam_forbidden") {
146	        paint("seam", "blocker");
147	    } else if (kind == "hidden" || kind == "seam_preferred") {
148	        paint("seam", "enforcer");
149	    } else if (kind == "material") {
150	        painted ? paint("color", std::to_string(record.extruder)) : volume("modifier");
151	    } else if (type == "object") { // reinforce, flexible
152	        for (const auto& [key, value] : record.settings)
153	            plan.push_back({"override", key, value, {}, 0, {}});
154	    } else {
155	        volume("modifier");
156	    }
157	    return plan;
158	}
