160	inline nlohmann::json region_vec3_json(const Vec3& value) { return nlohmann::json::array({value[0], value[1], value[2]}); }
161	
162	inline Vec3 region_vec3_from(const nlohmann::json& value)
163	{
164	    Vec3 result{0, 0, 0};
165	    if (value.is_array() && value.size() == 3)
166	        for (std::size_t index = 0; index < 3; ++index)
167	            if (value[index].is_number())
168	                result[index] = value[index].get<double>();
169	    return result;
170	}
171	
172	// The stored form. Readers take what they understand and default the rest, so
173	// a record written by a newer build loads.
174	inline nlohmann::json region_record_json(const RegionRecord& record)
175	{
176	    using nlohmann::json;
177	    json artifacts = json::array();
178	    for (const RegionArtifact& artifact : record.artifacts)
179	        artifacts.push_back({{"type", artifact.type}, {"target", artifact.target}, {"state", artifact.state},
180	                             {"name", artifact.name}, {"part", artifact.part}, {"facets", artifact.facets}});
181	    const RegionGeometry& g = record.geometry;
182	    return {{"regionId", record.id},
183	            {"kind", record.kind},
184	            {"label", record.label},
185	            {"object", {{"session", record.session}, {"id", record.object}, {"name", record.object_name},
186	                        {"partFacets", record.part_facets}, {"part", record.part}}},
187	            {"geometry", {{"type", g.type}, {"center", region_vec3_json(g.center)}, {"normal", region_vec3_json(g.normal)},
188	                          {"size", region_vec3_json(g.size)}, {"area", g.area}, {"diameter", g.diameter}, {"length", g.length},
189	                          {"toleranceDegrees", g.tolerance_degrees}}},
190	            {"settings", record.settings},
191	            {"extruder", record.extruder},
192	            {"artifacts", std::move(artifacts)},
193	            {"provenance", record.provenance},
194	            {"seq", record.seq},
195	            {"updatedAt", record.updated_at}};
196	}
197	
198	inline RegionRecord region_record_from(const nlohmann::json& value)
199	{
200	    RegionRecord record;
201	    if (!value.is_object())
202	        return record;
203	    const auto text = [](const nlohmann::json& object, const char* key) {
204	        return object.contains(key) && object[key].is_string() ? object[key].get<std::string>() : std::string();
205	    };
206	    const auto number = [](const nlohmann::json& object, const char* key) {
207	        return object.contains(key) && object[key].is_number() ? object[key].get<double>() : 0.0;
208	    };
209	    const auto whole = [](const nlohmann::json& object, const char* key) {
210	        return object.contains(key) && object[key].is_number_unsigned() ? object[key].get<std::uint64_t>() : std::uint64_t{0};
211	    };
212	    record.id         = text(value, "regionId");
213	    record.kind       = text(value, "kind");
214	    record.label      = text(value, "label");
215	    record.provenance = text(value, "provenance");
216	    record.updated_at = text(value, "updatedAt");
217	    record.seq        = whole(value, "seq");
218	    if (value.contains("object") && value["object"].is_object()) {
219	        const nlohmann::json& object = value["object"];
220	        record.session     = whole(object, "session");
221	        record.object      = whole(object, "id");
222	        record.object_name = text(object, "name");
223	        record.part        = static_cast<std::size_t>(whole(object, "part"));
224	        if (object.contains("partFacets") && object["partFacets"].is_array())
225	            for (const nlohmann::json& count : object["partFacets"])
226	                if (count.is_number_unsigned())
227	                    record.part_facets.push_back(count.get<std::size_t>());
228	    }
229	    if (value.contains("geometry") && value["geometry"].is_object()) {
230	        const nlohmann::json& g = value["geometry"];
231	        record.geometry.type              = text(g, "type");
232	        record.geometry.center            = region_vec3_from(g.value("center", nlohmann::json()));
233	        record.geometry.normal            = region_vec3_from(g.value("normal", nlohmann::json()));
234	        record.geometry.size              = region_vec3_from(g.value("size", nlohmann::json()));
235	        record.geometry.area              = number(g, "area");
236	        record.geometry.diameter          = number(g, "diameter");
237	        record.geometry.length            = number(g, "length");
238	        record.geometry.tolerance_degrees = number(g, "toleranceDegrees");
239	    }
240	    if (value.contains("settings") && value["settings"].is_object())
241	        for (const auto& [key, setting] : value["settings"].items())
242	            if (setting.is_string())
243	                record.settings[key] = setting.get<std::string>();
244	    if (value.contains("extruder") && value["extruder"].is_number_integer())
245	        record.extruder = value["extruder"].get<int>();
246	    if (value.contains("artifacts") && value["artifacts"].is_array())
247	        for (const nlohmann::json& item : value["artifacts"]) {
248	            if (!item.is_object())
249	                continue;
250	            RegionArtifact artifact;
251	            artifact.type   = text(item, "type");
252	            artifact.target = text(item, "target");
253	            artifact.state  = text(item, "state");
254	            artifact.name   = text(item, "name");
255	            artifact.part   = static_cast<std::size_t>(whole(item, "part"));
256	            if (item.contains("facets") && item["facets"].is_array())
257	                for (const nlohmann::json& facet : item["facets"])
258	                    if (facet.is_number_integer())
259	                        artifact.facets.push_back(facet.get<int>());
260	            record.artifacts.push_back(std::move(artifact));
261	        }
262	    if (record.provenance.empty())
263	        record.provenance = "user_confirmed";
264	    return record;
265	}
266	
267	// The next unused id: r1, r2, ... never reusing one still stored.
268	inline std::string next_region_id(const std::vector<RegionRecord>& stored, const std::vector<RegionRecord>& planned)
269	{
270	    unsigned highest = 0;
271	    for (const auto* list : {&stored, &planned})
272	        for (const RegionRecord& record : *list)
273	            if (record.id.size() > 1 && record.id[0] == 'r')
274	                highest = std::max<unsigned>(highest, static_cast<unsigned>(std::strtoul(record.id.c_str() + 1, nullptr, 10)));
275	    return "r" + std::to_string(highest + 1);
276	}
277	
278	} // namespace Slic3r::GUI::JusPrin::Workspace
