33	// A painted facet's state, read without the GUI's selector. The original
34	// facets are the first entries of the selector's triangle list.
35	class PaintReader : public TriangleSelector
36	{
37	public:
38	    using TriangleSelector::TriangleSelector;
39	    bool painted(int facet, EnforcerBlockerType state) const
40	    {
41	        if (facet < 0 || facet >= static_cast<int>(m_triangles.size()))
42	            return false;
43	        const Triangle& triangle = m_triangles[facet];
44	        return triangle.valid() && !triangle.is_split() && triangle.get_state() == state;
45	    }
46	};
