48	std::vector<std::size_t> part_facets(const ModelObject& object)
49	{
50	    std::vector<std::size_t> counts;
51	    for (const ModelVolume* part : model_parts(object))
52	        counts.push_back(part->mesh().facets_count());
53	    return counts;
54	}
55	
56	FacetsAnnotation& paint_layer(ModelVolume& part, const std::string& target)
57	{
58	    return target == "support" ? part.supported_facets : target == "seam" ? part.seam_facets : part.mmu_segmentation_facets;
59	}
60	
61	EnforcerBlockerType paint_state(const std::string& state)
62	{
63	    if (state == "enforcer")
64	        return EnforcerBlockerType::ENFORCER;
65	    if (state == "blocker")
66	        return EnforcerBlockerType::BLOCKER;
67	    return static_cast<EnforcerBlockerType>(std::stoi(state));
68	}
69	
70	ModelVolumeType volume_type(const std::string& target)
71	{
72	    return target == "support_blocker"  ? ModelVolumeType::SUPPORT_BLOCKER :
73	           target == "support_enforcer" ? ModelVolumeType::SUPPORT_ENFORCER : ModelVolumeType::PARAMETER_MODIFIER;
74	}
75	
76	int find_volume(const ModelObject& object, const RegionArtifact& artifact)
77	{
78	    for (std::size_t index = 0; index < object.volumes.size(); ++index)
79	        if (object.volumes[index]->name == artifact.name && object.volumes[index]->type() == volume_type(artifact.target))
80	            return static_cast<int>(index);
81	    return -1;
82	}
