20	struct RegionKindInfo
21	{
22	    const char*              name;
23	    const char*              words;      // how a card says it
24	    std::vector<std::string> geometries; // the geometry types it accepts
25	};
26	
27	inline const std::vector<RegionKindInfo>& region_kinds()
28	{
29	    static const std::vector<RegionKindInfo> kinds{
30	        {"smooth_face", "smooth face", {"face", "direction"}},
31	        {"no_support", "no support", {"face", "hole", "box", "cylinder", "direction"}},
32	        {"support_allowed", "support allowed", {"face", "box", "cylinder", "direction"}},
33	        {"precision_hole", "precision hole", {"hole"}},
34	        {"reinforce", "reinforce", {"hole", "box", "cylinder", "object"}},
35	        {"flexible", "flexible", {"box", "cylinder", "object"}},
36	        {"visible", "visible", {"face", "direction"}},
37	        {"hidden", "hidden", {"face", "direction"}},
38	        {"seam_preferred", "seam here", {"face", "direction"}},
39	        {"seam_forbidden", "no seam here", {"face", "direction"}},
40	        {"material", "material", {"face", "box", "cylinder", "direction"}},
41	    };
42	    return kinds;
43	}
44	
45	inline const RegionKindInfo* region_kind(const std::string& name)
46	{
47	    for (const RegionKindInfo& kind : region_kinds())
48	        if (name == kind.name)
49	            return &kind;
50	    return nullptr;
51	}
52	
53	inline bool region_kind_accepts(const std::string& kind, const std::string& geometry)
54	{
55	    const RegionKindInfo* info = region_kind(kind);
56	    return info && std::find(info->geometries.begin(), info->geometries.end(), geometry) != info->geometries.end();
57	}
58	
59	// The settings a kind writes when the request names none. Reinforcing adds
60	// walls and infill; flexible thins them. Values are relative to nothing: they
61	// are what the region prints with.
62	inline std::map<std::string, std::string> region_default_settings(const std::string& kind)
63	{
64	    if (kind == "reinforce")
65	        return {{"wall_loops", "5"}, {"sparse_infill_density", "40%"}};
66	    if (kind == "flexible")
67	        return {{"wall_loops", "1"}, {"sparse_infill_density", "5%"}};
68	    return {};
69	}
