86	std::optional<std::size_t> OrcaWorkspaceAdapter::region_object(const RegionRecord& record) const
87	{
88	    const Model& model = m_plater.model();
89	    std::optional<std::size_t> by_name;
90	    for (std::size_t index = 0; index < model.objects.size(); ++index) {
91	        const ModelObject& object = *model.objects[index];
92	        if (part_facets(object) != record.part_facets)
93	            continue;
94	        if (record.session == m_session.value() && object.id().id == record.object)
95	            return index;
96	        if (!by_name && object.name == record.object_name)
97	            by_name = index;
98	    }
99	    return by_name;
100	}
101	
102	CommandResult OrcaWorkspaceAdapter::plan_regions(const std::vector<RegionRequest>& requests, const std::vector<RegionRecord>& stored,
103	                                                 std::vector<RegionRecord>& planned) const
104	{
105	    wxASSERT(wxIsMainThread());
106	    planned.clear();
107	    if (requests.empty() || requests.size() > kRegionLimit)
108	        return CommandResult::failure(WorkspaceError::InvalidArgument, "Annotate 1 to 32 regions at a time");
109	    const Model& model = m_plater.model();
110	    std::set<std::string> seen;
111	    for (const RegionRequest& request : requests) {
112	        const RegionRecord* existing = nullptr;
113	        if (!request.region_id.empty()) {
114	            for (const RegionRecord& record : stored)
115	                if (record.id == request.region_id)
116	                    existing = &record;
117	            if (existing == nullptr)
118	                return CommandResult::failure(WorkspaceError::NotFound,
119	                                              "There is no region " + request.region_id + "; read object_analyze's regions section");
120	            if (!seen.insert(request.region_id).second)
121	                return CommandResult::failure(WorkspaceError::InvalidArgument, "Region " + request.region_id + " is named twice");
122	        }
123	        RegionRecord record;
124	        record.kind = request.kind.empty() && existing ? existing->kind : request.kind;
125	        if (!region_kind(record.kind))
126	            return CommandResult::failure(WorkspaceError::InvalidArgument, "\"" + record.kind + "\" is not a region kind");
127	        const std::string geometry_type = request.geometry ? request.geometry->type : existing ? existing->geometry.type : std::string();
128	        if (!geometry_type.empty() && !region_kind_accepts(record.kind, geometry_type))
129	            return CommandResult::failure(WorkspaceError::InvalidArgument, "A " + record.kind + " region cannot be a " + geometry_type);
130	
131	        std::optional<std::size_t> index;
132	        if (request.object) {
133	            const auto resolved = resolve(*request.object);
134	            if (!resolved)
135	                return id_error(*request.object);
136	            index = resolved->index;
137	        } else if (existing) {
138	            index = region_object(*existing);
139	            if (!index)
140	                return CommandResult::failure(WorkspaceError::StaleId,
141	                                              "Region " + existing->id + "'s object is not in the project; annotate it again with an objectId");
142	        } else {
143	            return CommandResult::failure(WorkspaceError::InvalidArgument, "A new region needs an objectId");
144	        }
145	        const ModelObject& object = *model.objects[*index];
146	        const auto         parts  = model_parts(object);
147	        if (parts.empty() || object.instances.empty())
148	            return CommandResult::failure(WorkspaceError::Refused, object.name + " has no solid part to annotate");
149	        if (!request.object && existing && request.geometry == std::nullopt && existing->part >= parts.size())
150	            return CommandResult::failure(WorkspaceError::StaleId, "Region " + existing->id + "'s part is gone");
151	
152	        record.id          = existing ? existing->id : next_region_id(stored, planned);
153	        record.session     = m_session.value();
154	        record.object      = object.id().id;
155	        record.object_name = object.name;
156	        record.part_facets = part_facets(object);
157	
158	        if (request.geometry) {
159	            const RegionGeometry& asked = *request.geometry;
160	            record.geometry.type        = asked.type;
161	            if (!asked.handle.empty()) {
162	                const auto address = parse_feature_handle(asked.handle);
163	                if (!address || address->object != object.id().id || address->volume >= object.volumes.size() ||
164	                    !object.volumes[address->volume]->is_model_part())
165	                    return CommandResult::failure(WorkspaceError::InvalidArgument, asked.handle + " is not a feature of " + object.name);
166	                if (address->revision != m_changes.revision())
167	                    return CommandResult::failure(WorkspaceError::FeatureExpired,
168	                                                  "The project changed since " + asked.handle + " was read; analyze the object again");
169	                const ModelVolume&          part = *object.volumes[address->volume];
170	                const indexed_triangle_set& its  = part.mesh().its;
171	                const Measure::Measuring    measuring(its);
172	                if (address->plane >= measuring.get_num_of_planes() ||
173	                    address->feature >= static_cast<int>(measuring.get_plane_features(address->plane).size()))
174	                    return CommandResult::failure(WorkspaceError::InvalidArgument, asked.handle + " is not a feature of " + object.name);
175	                const Measure::SurfaceFeature& feature = measuring.get_plane_features(address->plane)[address->feature];
176	                record.part = static_cast<std::size_t>(std::find(parts.begin(), parts.end(), &part) - parts.begin());
177	                if (asked.type == "face" && feature.get_type() == Measure::SurfaceFeatureType::Plane) {
178	                    const std::vector<int>& facets = measuring.get_plane_triangle_indices(address->plane);
179	                    const auto&             first  = its.indices[facets.front()];
180	                    record.geometry.normal = vec3(plane_normal(measuring, address->plane).value_or(Vec3d::UnitZ()));
181	                    record.geometry.center = vec3(its.vertices[first[0]].cast<double>());
182	                    record.geometry.area   = facets_area(its, facets);
183	                } else if (asked.type == "hole" && feature.get_type() == Measure::SurfaceFeatureType::Circle) {
184	                    record.geometry = hole_from(its, measuring, address->plane, address->feature);
185	                } else {
186	                    return CommandResult::failure(WorkspaceError::InvalidArgument,
187	                                                  asked.handle + " is a " +
188	                                                      (feature.get_type() == Measure::SurfaceFeatureType::Circle ? "hole" :
189	                                                       feature.get_type() == Measure::SurfaceFeatureType::Plane  ? "face" : "edge") +
190	                                                      " handle, not a " + asked.type + " handle; use the handles listed under features " +
191	                                                      (asked.type == "hole" ? "holes" : "faces"));
192	                }
193	            } else if (asked.type == "box" || asked.type == "cylinder" || asked.type == "direction") {
194	                // Given as the object stands now; kept in the first part's mesh
195	                // frame, so moving the object later does not move the region.
196	                record.part                  = 0;
197	                const Transform3d world      = world_of(object, *parts.front());
198	                const Transform3d to_mesh    = world.inverse();
199	                const Matrix3d    linear     = world.linear();
200	                if (asked.type == "direction") {
201	                    const Vec3d direction = eigen(asked.normal);
202	                    if (direction.norm() < 1e-9 || asked.tolerance_degrees <= 0 || asked.tolerance_degrees > 90)
203	                        return CommandResult::failure(WorkspaceError::InvalidArgument, "A direction needs a vector and a tolerance of 0 to 90 degrees");
204	                    record.geometry.normal            = vec3((linear.transpose() * direction).normalized());
205	                    record.geometry.tolerance_degrees = asked.tolerance_degrees;
206	                } else {
207	                    record.geometry.center = vec3(to_mesh * eigen(asked.center));
208	                    if (asked.type == "box") {
209	                        // World-aligned now; stored as its extent along the part's axes.
210	                        const Vec3d half = 0.5 * eigen(asked.size);
211	                        if (half.minCoeff() <= 0)
212	                            return CommandResult::failure(WorkspaceError::InvalidArgument, "A box needs a positive size");
213	                        const Matrix3d back = linear.inverse();
214	                        Vec3d extent = Vec3d::Zero();
215	                        for (int axis = 0; axis < 3; ++axis)
216	                            extent += (back * (half[axis] * Vec3d::Unit(axis))).cwiseAbs();
217	                        record.geometry.size = vec3(2 * extent);
218	                    } else {
219	                        const Vec3d axis = eigen(asked.normal);
220	                        if (axis.norm() < 1e-9 || asked.diameter <= 0 || asked.length <= 0)
221	                            return CommandResult::failure(WorkspaceError::InvalidArgument, "A cylinder needs an axis, a diameter and a length");
222	                        const Vec3d mesh_axis = linear.inverse() * axis.normalized();
223	                        const double scale    = mesh_axis.norm();
224	                        record.geometry.normal   = vec3(mesh_axis.normalized());
225	                        record.geometry.length   = asked.length * scale;
226	                        record.geometry.diameter = asked.diameter * scale;
227	                    }
228	                }
229	            } else if (asked.type == "object") {
230	                record.part = 0;
231	            } else {
232	                return CommandResult::failure(WorkspaceError::InvalidArgument,
233	                                              "A " + asked.type + " region needs a handle from object_analyze");
234	            }
235	        } else if (existing) {
236	            record.geometry = existing->geometry;
237	            record.part     = existing->part;
238	        } else {
239	            return CommandResult::failure(WorkspaceError::InvalidArgument, "A new region needs a geometry");
240	        }
241	        if (!region_kind_accepts(record.kind, record.geometry.type))
242	            return CommandResult::failure(WorkspaceError::InvalidArgument,
243	                                          "A " + record.kind + " region cannot be a " + record.geometry.type);
244	
245	        record.extruder = request.extruder != 0 ? request.extruder : existing ? existing->extruder : 0;
246	        if (record.kind == "material") {
247	            const int filaments = static_cast<int>(wxGetApp().preset_bundle->filament_presets.size());
248	            if (record.extruder < 1 || record.extruder > filaments)
249	                return CommandResult::failure(WorkspaceError::InvalidArgument,
250	                                              "A material region needs an extruder from 1 to " + std::to_string(filaments));
251	        }
252	        record.settings = !request.settings.empty() ? request.settings :
253	                          existing && existing->kind == record.kind ? existing->settings : region_default_settings(record.kind);
254	        if (record.kind == "reinforce" || record.kind == "flexible") {
255	            DynamicPrintConfig check = wxGetApp().preset_bundle->prints.get_edited_preset().config;
256	            for (const auto& [key, value] : record.settings) {
257	                // A modifier volume carries region settings; an object override
258	                // may carry object settings too.
259	                const bool region = PrintRegionConfig().optptr(key) != nullptr;
260	                if (!writable_setting(key) || !(region || (record.geometry.type == "object" && object_setting(key))))
261	                    return CommandResult::failure(WorkspaceError::InvalidArgument, key + " cannot be set on a region");
262	                if (auto refused = set_setting_value(check, key, value))
263	                    return CommandResult::failure(WorkspaceError::InvalidArgument, key + ": " + *refused);
264	                record.settings[key] = check.option(key)->serialize();
265	            }
266	        } else if (!request.settings.empty()) {
267	            return CommandResult::failure(WorkspaceError::InvalidArgument, "Only reinforce and flexible regions take settings");
268	        }
269	
270	        record.artifacts = region_artifact_plan(record);
271	        for (RegionArtifact& artifact : record.artifacts) {
272	            if (artifact.type != "paint")
273	                continue;
274	            artifact.facets = facets_of(parts[record.part]->mesh().its, record.geometry);
275	            if (artifact.facets.empty())
276	                return CommandResult::failure(WorkspaceError::StaleId, "No facet of " + object.name + " matches that face");
277	        }
278	        record.label = region_label(record);
279	        planned.push_back(std::move(record));
280	    }
281	    return CommandResult::success();
282	}
