342	CommandResult OrcaWorkspaceAdapter::change_regions(const std::vector<RegionRecord>& removed, const std::vector<RegionRecord>& added,
343	                                                   const char* snapshot_name)
344	{
345	    Model& model = m_plater.model();
346	    // An open paint gizmo keeps its own copy of the paint and would write it
347	    // back over ours.
348	    m_plater.canvas3D()->get_gizmos_manager().reset_all_states();
349	    const ProjectStateTransaction transaction = m_plater.project_state_transaction();
350	    Plater::TakeSnapshot          snapshot(&m_plater, snapshot_name);
351	    std::set<std::size_t>         touched;
352	    for (const RegionRecord& record : removed)
353	        if (const auto index = region_object(record)) {
354	            remove_region_artifacts(*model.objects[*index], record);
355	            touched.insert(*index);
356	        }
357	    for (const RegionRecord& record : added) {
358	        const auto resolved = resolve(ObjectId(m_session, record.object));
359	        if (!resolved)
360	            return CommandResult::failure(WorkspaceError::StaleId, record.object_name + " is no longer in the project");
361	        RegionRecord generated = record;
362	        generate_region_artifacts(*model.objects[resolved->index], generated);
363	        touched.insert(resolved->index);
364	    }
365	    ObjectList* list = wxGetApp().obj_list();
366	    for (std::size_t index : touched) {
367	        if (list) {
368	            list->add_volumes_to_object_in_list(index);
369	            list->object_config_options_changed({model.objects[index], nullptr});
370	            list->update_info_items(index);
371	        }
372	        m_plater.changed_object(static_cast<int>(index));
373	        // Paint lives in the crash backup's per-object mesh file, as in Orca's paint tools.
374	        Slic3r::save_object_mesh(*model.objects[index]);
375	    }
376	    m_plater.notify_project_state_changed(ProjectStateChangeReason::Objects);
377	    return CommandResult::success();
378	}
