{
    ModelVolume* volume = object.add_volume(std::move(mesh), type);
    volume->name        = name;
    volume->config.set_key_value("extruder", new ConfigOptionInt(extruder));
    volume->source.is_from_builtin_objects = true;
    return *volume;
}

